const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const sharp=require('C:/Users/myles/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
(async()=>{const master=fs.readFileSync(path.join(__dirname,'1-master.png'));const regions=[{left:100,top:640,width:550,height:384},{left:250,top:565,width:120,height:75},{left:800,top:800,width:150,height:224},{left:650,top:850,width:886,height:174}];const patches=await Promise.all(regions.map(async r=>({input:await sharp(master).extract(r).png().toBuffer(),left:r.left,top:r.top})));const ledger=[];for(const [input,output] of [['1-low-candidate.png','1-fixed-contacts.png'],['2-mid-candidate.png','2-fixed-contacts.png']]){const src=fs.readFileSync(path.join(__dirname,input));const out=await sharp(src).composite(patches).png().toBuffer();fs.writeFileSync(path.join(__dirname,output),out);ledger.push({input,output,inputSha256:hash(src),outputSha256:hash(out)});}fs.copyFileSync(path.join(__dirname,'1-master.png'),path.join(__dirname,'3-fixed-contacts.png'));fs.writeFileSync(path.join(__dirname,'fixed-contacts-provenance.json'),JSON.stringify({method:'Authorized exact source-copy of stationary equipment and floor regions. No athlete pixels transformed.',masterSha256:hash(master),regions,ledger},null,2));})();

const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto');
const sharp=require('C:/Users/myles/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
(async()=>{
 const rows=[];
 const scans=[['near grip',600,380,480,120],['near left upright',800,260,330,50],['near right upright',800,550,610,50],['far right upright',800,820,880,50],['left rail cap',590,255,300,50],['head',100,490,655,120]];
 for(const file of ['3-fixed-contacts.png','2-fixed-contacts.png','1-fixed-contacts.png']){const bytes=fs.readFileSync(path.join(__dirname,file));const {data,info}=await sharp(bytes).removeAlpha().raw().toBuffer({resolveWithObject:true});const measures=scans.map(([name,y,x0,x1,t])=>{const xs=[];for(let x=x0;x<x1;x++){const p=(y*info.width+x)*3;if(Math.min(...data.subarray(p,p+3))>t)xs.push(x);}return {name,y,left:xs[0],right:xs.at(-1),width:xs.at(-1)-xs[0]+1};});rows.push({file,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),measures});}
 for(const row of rows)for(let i=0;i<row.measures.length;i++){const a=row.measures[i],b=rows[0].measures[i];a.leftDelta=a.left-b.left;a.rightDelta=a.right-b.right;a.widthPercent=100*(a.width/b.width-1);}
 fs.writeFileSync(path.join(__dirname,'contact-measurements.json'),JSON.stringify(rows,null,2));console.log(JSON.stringify(rows,null,2));
})();
